### C++

```cpp
#include <iostream>
#include <vector>
#include <string>
using namespace std;

string transformString(const string& s, const vector<pair<char, char>>& ops) {
    // mp[i] 表示初始颜色 ('a' + i) 最终会变成的颜色
    vector<char> mp(26);
    for (int i = 0; i < 26; i++) {
        mp[i] = 'a' + i;
    }

    // 依次处理每个法术
    for (auto& op : ops) {
        char x = op.first;
        char y = op.second;
        // 所有当前映射为 x 的初始颜色都改为 y
        for (int i = 0; i < 26; i++) {
            if (mp[i] == x) {
                mp[i] = y;
            }
        }
    }

    // 根据最终映射生成宝石序列
    string res = s;
    for (int i = 0; i < (int)res.size(); i++) {
        res[i] = mp[res[i] - 'a'];
    }
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int t;
    cin >> t;
    while (t--) {
        int n, q;
        cin >> n >> q;
        string s;
        cin >> s;

        vector<pair<char, char>> ops;
        ops.reserve(q);
        for (int i = 0; i < q; i++) {
            char x, y;
            cin >> x >> y;
            ops.push_back({x, y});
        }

        cout << transformString(s, ops) << '\n';
    }
    return 0;
}
